                        mat[row][col] = !mat[row][col];
                    }
                }
            }
            mat[row][total] = light[i][j];
        }
    }
}

int gauss() {
    int rank = 0;
    for (int col = 0; col < total && rank < total; col++) {
        // find pivot
        int sel = -1;
        for (int i = rank; i < total; i++) {
            if (mat[i][col]) {
                sel = i;
                break;
            }
        }
        if (sel == -1) continue;
        // swap rows
        for (int j = col; j <= total; j++) {
            bool tmp = mat[rank][j];
            mat[rank][j] = mat[sel][j];
            mat[sel][j] = tmp;
        }
        // eliminate other rows
        for (int i = 0; i < total; i++) {
            if (i != rank && mat[i][col]) {
                for (int j = col; j <= total; j++) {
                    mat[i][j] = mat[i][j] ^ mat[rank][j];
                }
            }
        }
        rank++;
    }
    // check for inconsistency
    for (int i = rank; i < total; i++) {
        if (mat[i][total]) return -1;
    }
    return rank;
}

