#define MAXN 300

int rows, cols, dist;
int light[MAXN][MAXN];
// Variables: switch[i][j] = (i*cols + j)
// Equations: for each (i,j): sum of switch[r][c] where |r-i|+|c-j|<=dist = light[i][j]

int n; // total variables = rows*cols
// augmented matrix for GF(2) gaussian elimination
// each row is a bitset
#define MAXVARS 300
#define WORDS ((MAXVARS+2)/32 + 2)
unsigned int mat[MAXVARS][WORDS+1];

void setbit(unsigned int *row, int col) {
    row[col/32] |= (1u << (col%32));
}
int getbit(unsigned int *row, int col) {
    return (row[col/32] >> (col%32)) & 1;
}
void xorrow(unsigned int *dst, unsigned int *src, int words) {
    for(int i=0;i<words;i++) dst[i]^=src[i];
}

int gaussian(int n, int words) {
    int pivot_row[MAXVARS];
    memset(pivot_row,-1,sizeof(pivot_row));
    int cur_row=0;
    for(int col=0;col<n && cur_row<n;col++) {
        int found=-1;
        for(int r=cur_row;r<n;r++) {
            if(getbit(mat[r],col)){found=r;break;}
        }
        if(found==-1) continue;
        // swap
        unsigned int tmp[WORDS+1];
        memcpy(tmp,mat[cur_row],(words)*sizeof(unsigned int));
        memcpy(mat[cur_row],mat[found],(words)*sizeof(unsigned int));
        memcpy(mat[found],tmp,(words)*sizeof(unsigned int));
        pivot_row[col]=cur_row;
        for(int r=0;r<n;r++) {
            if(r!=cur_row && getbit(mat[r],col)) {
                xorrow(mat[r],mat[cur_row],words);
            }
        }
        cur_row++;
    }
    // check consistency
    for(int r=0;r<n;r++) {
        int allzero=1;
        for(int c=0;c<n;c++) if(getbit(mat[r],c)){allzero=0;break;}
        if(allzero && getbit(mat[r],n)) return 0; // inconsistent
    }
    return 1;
}

