/*
The statement available here is incomplete, but the core described task is:

- We have an n x m grid of lights (current on/off states).
- Pressing/toggling a room switch flips the lights in all rooms whose Manhattan
  distance from that room is <= d.
- Determine whether it is possible to turn off all lights.

This is a linear-algebra-over-GF(2) reachability problem:
Let x_(i,j) be whether we press switch (i,j).
For each cell (r,c), the final state is:
  initial[r][c] XOR sum of x_(i,j) over all (i,j) with |i-r|+|j-c| <= d
We need all final states = 0.

So we solve A x = b over GF(2), where:
- A[p][q] = 1 iff switch q affects cell p
- b[p] = initial state of cell p

If the system is consistent, answer YES, otherwise NO.

Because the exact input format was not provided, this program supports a common
flexible format:
- First line: n m d
- Then n lines containing the grid.
Accepted grid forms:
  * contiguous 0/1 characters, e.g. 0101
  * space-separated 0/1 integers

Output:
- "Yes" if solvable
- "No" otherwise

This is sufficient for the mathematical problem as described.
*/

static int get_bit(unsigned long long *row, int pos) {
    return (row[pos >> 6] >> (pos & 63)) & 1ULL;
}

static void xor_row(unsigned long long *a, unsigned long long *b, int words) {
    for (int i = 0; i < words; i++) a[i] ^= b[i];
}

int main(void) {
    int n, m, d;
    if (scanf("%d %d %d", &n, &m, &d) != 3) return 0;

    int vars = n * m;
    int eqs = vars;
    int cols = vars + 1;              // augmented column
    int words = (cols + 63) >> 6;

    int *initial = (int *)calloc(eqs, sizeof(int));
    if (!initial) return 0;

    char buf[10005];

    for (int i = 0; i < n; i++) {
        if (scanf("%10000s", buf) != 1) {
            free(initial);
            return 0;
        }

        int len = (int)strlen(buf);
        if (len == m) {
            for (int j = 0; j < m; j++) {
                initial[i * m + j] = (buf[j] == '1');
            }
        } else {
            initial[i * m + 0] = atoi(buf) & 1;
            for (int j = 1; j < m; j++) {
                int x;
                scanf("%d", &x);
                initial[i * m + j] = x & 1;
            }
        }
    }

    unsigned long long **mat = (unsigned long long **)malloc(eqs * sizeof(unsigned long long *));
    if (!mat) {
        free(initial);
        return 0;
    }
    for (int i = 0; i < eqs; i++) {
        mat[i] = (unsigned long long *)calloc(words, sizeof(unsigned long long));
        if (!mat[i]) return 0;
    }

    for (int r = 0; r < n; r++) {
        for (int c = 0; c < m; c++) {
            int row = r * m + c;

            for (int i = 0; i < n; i++) {
                int rem = d - abs(i - r);
                if (rem < 0) continue;
                int l = c - rem;
                int rr = c + rem;
                if (l < 0) l = 0;
                if (rr >= m) rr = m - 1;
                for (int j = l; j <= rr; j++) {
                    int col = i * m + j;
                    mat[row][col >> 6] ^= (1ULL << (col & 63));
                }
            }

            if (initial[row]) {
                int aug = vars;
                mat[row][aug >> 6] ^= (1ULL << (aug & 63));
            }
        }
    }

    int rank = 0;
    for (int col = 0; col < vars && rank < eqs; col++) {
        int pivot = -1;
        for (int r = rank; r < eqs; r++) {
            if (get_bit(mat[r], col)) {
                pivot = r;
                break;
            }
        }
        if (pivot == -1) continue;

        if (pivot != rank) {
            unsigned long long *tmp = mat[pivot];
            mat[pivot] = mat[rank];
            mat[rank] = tmp;
        }

        for (int r = 0; r < eqs; r++) {
            if (r != rank && get_bit(mat[r], col)) {
                xor_row(mat[r], mat[rank], words);
            }
        }
        rank++;
    }

    int ok = 1;
    for (int r = 0; r < eqs; r++) {
        int all_zero = 1;
        for (int c = 0; c < vars; c++) {
            if (get_bit(mat[r], c)) {
                all_zero = 0;
                break;
            }
        }
        if (all_zero && get_bit(mat[r], vars)) {
            ok = 0;
            break;
        }
    }

    printf(ok ? "Yes\n" : "No\n");

    for (int i = 0; i < eqs; i++) free(mat[i]);
    free(mat);
    free(initial);
    return 0;
}

