                for (int c = 0; c < C; c++) {
                    if (abs(r - i) + abs(c - j) <= D) {
                        int var = r * C + c;
                        mat[eq][var] = 1;
                    }
                }
            }
        }
    }

    // Gaussian elimination over GF(2)
    int pivot_row = 0;
    for (int col = 0; col < N && pivot_row < N; col++) {
        // Find pivot
        int found = -1;
        for (int row = pivot_row; row < N; row++) {
            if (mat[row][col] == 1) { found = row; break; }
        }
        if (found == -1) continue;
        swap(mat[pivot_row], mat[found]);
        // Eliminate
        for (int row = 0; row < N; row++) {
            if (row != pivot_row && mat[row][col] == 1) {
                for (int k = 0; k <= N; k++)
                    mat[row][k] ^= mat[pivot_row][k];
            }
        }
        pivot_row++;
    }

    // Check consistency
    for (int row = pivot_row; row < N; row++) {
        if (mat[row][N] == 1) {
