public class Main {
    static int N, M, D;
    static boolean[][] grid;
    static int totalRooms;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        N = sc.nextInt();
        M = sc.nextInt();
        D = sc.nextInt();
        totalRooms = N * M;
        grid = new boolean[N][M];
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < M; j++) {
                grid[i][j] = sc.nextInt() == 1;
            }
        }

        // Build the matrix: totalRooms equations, totalRooms variables
        int rows = totalRooms;
        int cols = totalRooms + 1; // +1 for augmented part (target state)
        BitSet[] matrix = new BitSet[rows];
        for (int i = 0; i < rows; i++) {
            matrix[i] = new BitSet(cols);
        }

        // Fill matrix
        for (int r = 0; r < N; r++) {
            for (int c = 0; c < M; c++) {
                int eqIdx = r * M + c;
                // set target: we want to turn off all lights, so target = current state
                if (grid[r][c]) {
                    matrix[eqIdx].set(cols - 1);
                }
                // set coefficients for each variable
                for (int r2 = 0; r2 < N; r2++) {
                    for (int c2 = 0; c2 < M; c2++) {
                        if (Math.abs(r - r2) + Math.abs(c - c2) <= D) {
                            int varIdx = r2 * M + c2;
                            matrix[eqIdx].set(varIdx);
                        }
                    }
                }
            }
        }

        // Gaussian elimination over GF(2)
        int row = 0;
        for (int col = 0; col < totalRooms && row < totalRooms; col++) {
            // Find pivot
            int pivot = -1;
            for (int i = row; i < totalRooms; i++) {
                if (matrix[i].get(col)) {
                    pivot = i;
                    break;
                }
            }
            if (pivot == -1) continue;

            // Swap
            BitSet temp = matrix[row];
            matrix[row] = matrix[pivot];
            matrix[pivot] = temp;

            // Eliminate other rows
            for (int i = 0; i < totalRooms; i++) {
                if (i != row && matrix[i].get(col)) {
                    matrix[i].xor(matrix[row]);
                }
            }
            row++;
        }

        // Check for inconsistency
        for (int i = 0; i < totalRooms; i++) {
            boolean allZero = true;
            for (int j = 0; j < totalRooms; j++) {
                if (matrix[i].get(j)) {
                    allZero = false;
                    break;
                }
            }
            if (allZero && matrix[i].get(totalRooms)) {
                System.out.println("IMPOSSIBLE");
                return;
            }
        }

        System.out.println("POSSIBLE");
    }
}

