public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt(), m = sc.nextInt(), d = sc.nextInt();
        int[] state = new int[n * m];
        for (int i = 0; i < n; i++)
            for (int j = 0; j < m; j++)
                state[i * m + j] = sc.nextInt();

        int vars = n * m;
        // Build augmented matrix [A | b] over GF(2)
        // Using long arrays as bitsets for efficiency
        int cols = vars + 1;
        int words = (cols + 63) / 64;
        long[][] mat = new long[vars][words];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int row = i * m + j;
                // This switch affects all (r,c) within Manhattan distance d
                for (int r = 0; r < n; r++) {
                    for (int c = 0; c < m; c++) {
                        if (Math.abs(r - i) + Math.abs(c - j) <= d) {
                            int col = r * m + c;
                            mat[col][col / 64] ^= (1L << (col % 64));
                        }
                    }
                }
                // b part: state[row]
                if (state[row] == 1) {
                    mat[row][vars / 64] ^= (1L << (vars % 64));
                }
            }
        }

        // Gaussian elimination over GF(2)
        int rank = 0;
        for (int col = 0; col < vars && rank < vars; col++) {
            // Find pivot
            int pivot = -1;
            for (int r = rank; r < vars; r++) {
                if (((mat[r][col / 64] >> (col % 64)) & 1) == 1) {
                    pivot = r;
                    break;
                }
            }
            if (pivot == -1) continue;
            long[] tmp = mat[rank]; mat[rank] = mat[pivot]; mat[pivot] = tmp;
            for (int r = 0; r < vars; r++) {
                if (r != rank && ((mat[r][col / 64] >> (col % 64)) & 1) == 1) {
                    for (int w = 0; w < words; w++) mat[r][w] ^= mat[rank][w];
                }
            }
            rank++;
        }

        // Check consistency
        boolean possible = true;
        for (int r = rank; r < vars; r++) {
            if (((mat[r][vars / 64] >> (vars % 64)) & 1) == 1) {
                possible = false;
                break;
            }
        }

        System.out.println(possible ? "YES" : "NO");
    }
}

import java.io.*;
import java.util.*;

/*
The statement provided is incomplete: it describes a grid of lights and switches,
where pressing a switch toggles all cells within a given Manhattan distance, and
asks whether all lights can be turned off.

A standard interpretation of this task is:
- Input: n, m, d
- Then n lines of a binary grid (0/1), where 1 means light is on.
- Pressing a switch at (i, j) toggles every cell (x, y) such that
  |x - i| + |y - j| <= d.
- Each switch may be pressed any number of times, but over GF(2) only parity matters.
- Determine whether there exists a set of presses that turns all lights off.

This becomes a linear system over GF(2):
A * x = b
where:
- x represents whether each switch is pressed
- b is the initial grid
- A[r][c] = 1 iff switch c affects light r

We solve by Gaussian elimination over BitSet.

If your judge uses a different exact input format, you may need to adapt parsing.
This implementation expects:
n m d
row1
row2
...
rown

Each row may be:
- a string of length m containing only 0/1, or
- m integers separated by spaces.

Output:
YES if solvable, otherwise NO.
*/
public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            String s = next();
            return s == null ? Integer.MIN_VALUE : Integer.parseInt(s);
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        String first = fs.next();
        if (first == null) return;
        int n = Integer.parseInt(first);
        int m = fs.nextInt();
        int d = fs.nextInt();

        int vars = n * m;
        BitSet[] rows = new BitSet[vars];
        for (int i = 0; i < vars; i++) rows[i] = new BitSet(vars + 1);

        int[] b = new int[vars];

        for (int i = 0; i < n; i++) {
            String s = fs.next();
            if (s == null) return;

            if (s.length() == m && isBinaryString(s)) {
                for (int j = 0; j < m; j++) {
                    b[i * m + j] = s.charAt(j) - '0';
                }
            } else {
                b[i * m] = Integer.parseInt(s);
                for (int j = 1; j < m; j++) {
                    b[i * m + j] = fs.nextInt();
                }
            }
        }

        for (int x = 0; x < n; x++) {
            for (int y = 0; y < m; y++) {
                int eq = x * m + y;
                BitSet row = rows[eq];

                for (int i = 0; i < n; i++) {
                    int rem = d - Math.abs(i - x);
                    if (rem < 0) continue;
                    int left = Math.max(0, y - rem);
                    int right = Math.min(m - 1, y + rem);
                    for (int j = left; j <= right; j++) {
                        int var = i * m + j;
                        row.set(var);
                    }
                }
                if ((b[eq] & 1) == 1) row.set(vars);
            }
        }

        boolean ok = gaussian(rows, vars);
        System.out.println(ok ? "YES" : "NO");
    }

    static boolean isBinaryString(String s) {
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c != '0' && c != '1') return false;
        }
        return true;
    }

    static boolean gaussian(BitSet[] a, int vars) {
        int n = a.length;
        int row = 0;

        for (int col = 0; col < vars && row < n; col++) {
            int sel = -1;
            for (int i = row; i < n; i++) {
                if (a[i].get(col)) {
                    sel = i;
                    break;
                }
            }
            if (sel == -1) continue;

            BitSet tmp = a[row];
            a[row] = a[sel];
            a[sel] = tmp;

            for (int i = 0; i < n; i++) {
                if (i != row && a[i].get(col)) {
                    a[i].xor(a[row]);
                }
            }
            row++;
        }

        for (int i = 0; i < n; i++) {
            int first = a[i].nextSetBit(0);
            if (first == vars) return false; // 0 ... 0 | 1
        }
        return true;
    }
}

import sys

def solve():
    input_data = sys.stdin.read().strip().split()
    if not input_data:
        return
    it = iter(input_data)
    n = int(next(it))
    m = int(next(it))
    d = int(next(it))

    grid = []
    for _ in range(n):
        row = []
        for _ in range(m):
            row.append(int(next(it)))
        grid.append(row)

    # Flatten grid to vector b
    b = []
    for i in range(n):
        for j in range(m):
            b.append(grid[i][j])

    N = n * m
    # Build matrix A (N x N) over GF(2)
    A = [[0] * N for _ in range(N)]

    def idx(r, c):
        return r * m + c

    for r in range(n):
        for c in range(m):
            cur = idx(r, c)
            for nr in range(n):
                for nc in range(m):
                    if abs(r - nr) + abs(c - nc) <= d:
                        A[cur][idx(nr, nc)] ^= 1

    # Gaussian elimination over GF(2)
    row = 0
    col = 0
    where = [-1] * N
    while col < N and row < N:
        # Find pivot
        sel = row
        while sel < N and A[sel][col] == 0:
            sel += 1
        if sel == N:
            col += 1
            continue
        # Swap rows
        A[row], A[sel] = A[sel], A[row]
        b[row], b[sel] = b[sel], b[row]
        where[col] = row

        # Eliminate other rows
        for r in range(N):
            if r != row and A[r][col] == 1:
                for c in range(col, N):
                    A[r][c] ^= A[row][c]
                b[r] ^= b[row]
        row += 1
        col += 1

    # Check for inconsistency
    for r in range(row, N):
        if b[r] != 0:
            print("IMPOSSIBLE")
            return

    print("POSSIBLE")

if __name__ == "__main__":
    solve()
